import{_ as o,r as a,o as d,c as r,e,a as l,s as c}from"./chunks/framework.CXcwiNg-.js";const f=JSON.parse('{"title":"Поле Tag List - October CMS - 3.x","titleTemplate":false,"description":"Виджет формы","frontmatter":{"subtitle":"Виджет формы","shortname":"Tag List"},"headers":[{"level":4,"title":"См. также","slug":"см-также","link":"#см-также","children":[]}],"relativePath":"3.x/ru/element/form/widget-taglist.md","filePath":"3.x/ru/element/form/widget-taglist.md"}'),p={name:"3.x/ru/element/form/widget-taglist.md"};function i(g,t,u,m,k,h){const s=a("pre-heading"),n=a("post-heading");return d(),r("div",null,[e(s),t[0]||(t[0]=l("h1",null,"Поле Tag List",-1)),e(n),t[1]||(t[1]=c(`<p>Виджет формы <code>taglist</code> рендерит поле для ввода списка тегов.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">tags</span><span class="token punctuation">:</span>
    <span class="token key atrule">type</span><span class="token punctuation">:</span> taglist
    <span class="token key atrule">separator</span><span class="token punctuation">:</span> space
</code></pre></div><p>Поддерживаются и обычно используются следующие <a href="./../form-fields.html">свойства поля</a>.</p><div class="table"><table tabindex="0"><thead><tr><th>Свойство</th><th>Описание</th></tr></thead><tbody><tr><td><strong>label</strong></td><td>имя при отображении поля формы пользователю.</td></tr><tr><td><strong>default</strong></td><td>значение по умолчанию (строка), необязательно.</td></tr><tr><td><strong>comment</strong></td><td>пояснительный комментарий под полем.</td></tr><tr><td><strong>mode</strong></td><td>управляет форматом возвращаемого значения: <code>string</code>, <code>array</code> или <code>relation</code>. По умолчанию: <code>string</code></td></tr><tr><td><strong>separator</strong></td><td>разделяет теги указанным символом: <code>comma</code> или <code>space</code>. По умолчанию: <code>comma</code></td></tr><tr><td><strong>customTags</strong></td><td>разрешает пользователю вводить произвольные теги вручную. По умолчанию: <code>true</code></td></tr><tr><td><strong>options</strong></td><td>задаёт массив предопределённых вариантов.</td></tr><tr><td><strong>optionsMethod</strong></td><td>задаёт имя метода для предопределённых вариантов, определённого в модели или как статический метод, например <code>Class::method</code>. Установите в <code>true</code> для использования метода модели <strong>get<em>Field</em>Options</strong>.</td></tr><tr><td><strong>nameFrom</strong></td><td>при использовании режима relation — имя атрибута модели для отображения названия тега. По умолчанию: <code>name</code></td></tr><tr><td><strong>useKey</strong></td><td>использовать ключ вместо значения для сохранения и чтения данных. По умолчанию: <code>false</code></td></tr><tr><td><strong>maxItems</strong></td><td>максимальное количество тегов, которые можно добавить или выбрать.</td></tr></tbody></table></div><p>Список тегов поддерживает те же методы определения вариантов, что и <a href="./field-dropdown.html">тип поля dropdown</a>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">tags</span><span class="token punctuation">:</span>
    <span class="token key atrule">type</span><span class="token punctuation">:</span> taglist
    <span class="token key atrule">options</span><span class="token punctuation">:</span>
        <span class="token punctuation">-</span> Red
        <span class="token punctuation">-</span> Blue
        <span class="token punctuation">-</span> Orange
</code></pre></div><p>Вы можете использовать <code>mode</code> со значением <strong>relation</strong>, где имя поля является <a href="./../../extend/database/relations.html">отношением многие-ко-многим</a>. Это автоматически будет получать и назначать теги через отношение. Если поддерживаются произвольные теги, они будут созданы перед назначением.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">tags</span><span class="token punctuation">:</span>
    <span class="token key atrule">type</span><span class="token punctuation">:</span> taglist
    <span class="token key atrule">mode</span><span class="token punctuation">:</span> relation
</code></pre></div><h4 id="см-также"><a href="#см-также" class="header-anchor">#</a> См. также</h4><div class="custom-block also"><ul><li><a href="./field-dropdown.html">Поле формы Dropdown</a></li></ul></div>`,10))])}const y=o(p,[["render",i]]);export{f as __pageData,y as default};
